#!/usr/bin/env bash
set -euo pipefail

cd "$(dirname "$0")/.."

if [ -f .env ] && grep -q '^POSTGRES_PASSWORD=' .env; then
  echo ".env already contains POSTGRES_PASSWORD; leaving it untouched."
  exit 0
fi

if ! command -v openssl >/dev/null 2>&1; then
  echo "openssl is required to generate the database password." >&2
  exit 1
fi

password="$(openssl rand -hex 32)"
cat > .env <<EOF
# Generated by scripts/setup.sh. Keep this file private.
POSTGRES_PASSWORD=${password}
APP_PORT=3000
EOF

chmod 600 .env
echo "Created .env with a generated database password."
echo "Next: docker compose up -d --build"
